/* =========================================================================
   BORING — Agenda "Car" Scroll Animation (v4)
   Slater-ready IIFE. Assumes GSAP + ScrollTrigger are already loaded globally
   (and that your boilerplate wires Lenis -> ScrollTrigger.update; a guarded
   safety net is included below in case it doesn't).

   v4 changes (MOBILE SNAP FIX):
   - ignoreMobileResize: the mobile address bar collapsing/expanding on a
     scroll-direction change fires a resize -> ScrollTrigger.refresh() ->
     syncCar() hard-set the car mid-view (position teleport + rotation reset
     to 0 = the "snap"). ScrollTrigger now ignores height-only resizes.
   - STATE-AWARE syncCar: the car's logical state (above / in / below) is
     tracked by the drive functions. syncCar only writes when the computed
     state genuinely differs (real layout change, e.g. orientation flip),
     and it never resets rotation while the car is in view — so no more
     instant 180° flips.

   Still in from v3:
   - Runs on ALL breakpoints.
   - NO-FLICKER LOAD: set the car element to 0% opacity in Webflow. The JS
     hides it immediately as a fallback, then positions it off-screen AND
     reveals it (autoAlpha: 1) in one gsap.set — both land before the next
     paint, so the car is never seen at its authored position.
   ========================================================================= */
(function () {
  "use strict";

  if (typeof window.gsap === "undefined") {
    console.warn("[agenda-car] GSAP not found — aborting.");
    return;
  }
  gsap.registerPlugin(ScrollTrigger);

  // THE FIX (part 1): don't let the mobile URL bar's show/hide (a height-only
  // resize that happens exactly when scroll direction changes) trigger a
  // ScrollTrigger.refresh(). Width changes / orientation flips still refresh.
  ScrollTrigger.config({ ignoreMobileResize: true });

  /* ------------------------------------------------------------------ *
   *  TWEAK ME — everything you'll want to play with lives here.
   * ------------------------------------------------------------------ */
  const CONFIG = {
    // CAR — drive IN (arriving: decelerates to a stop at centre)
    carInDuration: 0.8,
    carInEase: "expo.out",

    // CAR — drive OUT (leaving: accelerates away)
    carOutDuration: 0.8,
    carOutEase: "expo.in",

    // Where the start/end markers fire the car.
    // "top center" = marker's top edge hits the vertical middle of the viewport.
    carStart: "top center", // [data-agenda="start"]
    carEnd: "bottom center", // [data-agenda="end"]

    // ITEMS — the yellow "trail"
    highlightColor: "#fed60a",
    yellowDuration: 0.2, // snap to yellow
    yellowEase: "power2.out",
    resetDuration: 0.6, // slow fade back -> the trail behind the car
    resetEase: "power2.inOut",

    // ITEM trigger band: top hits centre -> ON, bottom hits centre -> OFF
    itemStart: "top center",
    itemEnd: "bottom center",

    // Flip the ScrollTrigger markers on while you're dialling things in.
    debug: false,
  };
  /* ------------------------------------------------------------------ */

  const car = document.querySelector('[data-agenda="car"]');
  const startEl = document.querySelector('[data-agenda="start"]');
  const endEl = document.querySelector('[data-agenda="end"]');
  const items = gsap.utils.toArray('[data-agenda="item"]');

  // Lenis safety net — no-op if your boilerplate already does this.
  if (window.lenis && typeof window.lenis.on === "function") {
    window.lenis.on("scroll", ScrollTrigger.update);
  }

  /* ----------------------------- ITEMS ----------------------------- */
  items.forEach((item) => {
    const line = item.querySelector('[data-agenda="line"]');
    const baseColor = gsap.getProperty(item, "color");
    const baseLineBg = line ? gsap.getProperty(line, "backgroundColor") : null;

    const highlight = () => {
      gsap.to(item, {
        color: CONFIG.highlightColor,
        duration: CONFIG.yellowDuration,
        ease: CONFIG.yellowEase,
        overwrite: "auto",
      });
      if (line) gsap.to(line, {
        backgroundColor: CONFIG.highlightColor,
        duration: CONFIG.yellowDuration,
        ease: CONFIG.yellowEase,
        overwrite: "auto",
      });
    };

    const reset = () => {
      gsap.to(item, {
        color: baseColor,
        duration: CONFIG.resetDuration,
        ease: CONFIG.resetEase,
        overwrite: "auto",
      });
      if (line) gsap.to(line, {
        backgroundColor: baseLineBg,
        duration: CONFIG.resetDuration,
        ease: CONFIG.resetEase,
        overwrite: "auto",
      });
    };

    ScrollTrigger.create({
      trigger: item,
      start: CONFIG.itemStart,
      end: CONFIG.itemEnd,
      onEnter: highlight, // top crosses centre (scrolling down)
      onLeave: reset, // bottom crosses centre (scrolling down)
      onEnterBack: highlight, // bottom crosses centre (scrolling up)
      onLeaveBack: reset, // top crosses centre (scrolling up)
      markers: CONFIG.debug,
    });
  });

  /* ------------------------------ CAR ------------------------------ *
   *  Runs on every breakpoint. Never visible on load.
   * ------------------------------------------------------------------ */
  if (!car || !startEl || !endEl) {
    console.warn("[agenda-car] Missing car / start / end element — car animation skipped.");
    window.addEventListener("load", () => ScrollTrigger.refresh());
    return;
  }

  // JS fallback for the Webflow 0%-opacity setting: hide the car the moment
  // this file runs, so it's never seen at its authored centre position.
  gsap.set(car, { autoAlpha: 0 });

  const vh = (n) => (window.innerHeight * n) / 100;
  let carTween = null;

  // THE FIX (part 2a): the car's logical state, owned by the drive functions.
  // "above" = parked off the top, "in" = centre stage, "below" = off the bottom.
  let carState = "above";

  // Prime the car: off the top, pointing down, AND revealed — all in one
  // set, applied before the next paint => no flicker.
  gsap.set(car, {
    y: -vh(100),
    rotation: 0,
    autoAlpha: 1,
    force3D: true,
    willChange: "transform",
  });

  function drive(yTarget, duration, ease, onDone) {
    if (carTween) carTween.kill();
    carTween = gsap.to(car, {
      y: yTarget,
      duration: duration,
      ease: ease,
      force3D: true,
      overwrite: true,
      onComplete: onDone || null,
    });
    return carTween;
  }

  // Arriving (both from top and back-in from bottom): settle at centre.
  const driveIn = () => {
    carState = "in";
    return drive(0, CONFIG.carInDuration, CONFIG.carInEase);
  };

  // Leaving downward: launch off the bottom, then flip 180° while off-screen
  // so a scroll-back-up reads as the car driving back UP the page.
  const driveOutBottom = () => {
    carState = "below";
    return drive(vh(100), CONFIG.carOutDuration, CONFIG.carOutEase, () =>
      gsap.set(car, { rotation: 180 })
    );
  };

  // Leaving upward: launch off the top, then flip back to 0° so the next
  // downward pass reads as the car driving DOWN again.
  const driveOutTop = () => {
    carState = "above";
    return drive(-vh(100), CONFIG.carOutDuration, CONFIG.carOutEase, () =>
      gsap.set(car, { rotation: 0 })
    );
  };

  // START marker: drive IN as the list arrives; drive OUT the top on scroll-up.
  ScrollTrigger.create({
    trigger: startEl,
    start: CONFIG.carStart,
    onEnter: driveIn,
    onLeaveBack: driveOutTop,
    markers: CONFIG.debug,
  });

  // END marker: drive OUT the bottom as the next section arrives; back IN up.
  ScrollTrigger.create({
    trigger: endEl,
    start: CONFIG.carEnd,
    onEnter: driveOutBottom,
    onLeaveBack: driveIn,
    markers: CONFIG.debug,
  });

  // THE FIX (part 2b): syncCar is now a *corrector*, not a *setter*.
  // It only writes when the freshly measured state disagrees with the
  // logical state (a real layout change: orientation flip, desktop resize,
  // fonts/images settling). It never touches rotation while the car is
  // in view, so there's no instant 180° flip mid-screen.
  function syncCar() {
    if (carTween && carTween.isActive()) return;

    const mid = window.innerHeight / 2;
    const startTop = startEl.getBoundingClientRect().top;
    const endTop = endEl.getBoundingClientRect().top;

    let measured;
    if (startTop > mid) measured = "above";
    else if (endTop > mid) measured = "in";
    else measured = "below";

    if (measured === carState) return; // nothing to do — no snap.

    carState = measured;
    if (measured === "above") {
      gsap.set(car, { y: -vh(100), rotation: 0 });
    } else if (measured === "below") {
      gsap.set(car, { y: vh(100), rotation: 180 });
    } else {
      // In view: fix the position, keep whatever direction it was facing.
      gsap.set(car, { y: 0 });
    }
  }
  ScrollTrigger.addEventListener("refresh", syncCar);
  syncCar();

  // One more refresh once images/fonts have settled — keeps triggers honest.
  window.addEventListener("load", () => ScrollTrigger.refresh());
})();


